//! #274 host verification of the character-boundary display clip. Includes the real
//! `src/textclip.rs` verbatim (`#[path]`, no drift). Run: `cargo run` — panics on failure.
//!
//! # What is actually being defended
//!
//! `&s[..s.len().min(n)]` panics when `n` lands inside a multi-byte character. Two copies of
//! that lived in `bench.rs` and `rssi.rs`, each with a comment asserting the input was ASCII.
//! The inputs are sigil words from `rust/sigil-names/src/realms.rs` — a file whose own header
//! reads *"Generated by sync-words.sh from words/realms.json — DO NOT EDIT"*. So a fleet board's
//! freedom from panics depended on nobody upstream adding a word with an accent in it.
//!
//! This suite therefore does something a normal unit test does not: it keeps a **verbatim copy
//! of the old body** and proves it STILL PANICS on the motivating input. `clip` is three lines
//! and looks exactly like something a future cleanup would "simplify" back. If that happens,
//! `same_as_old_on_ascii` keeps passing — and `old_form_panics_new_does_not` is what fails.

#[path = "../../../rust/clock/src/textclip.rs"]
mod textclip;

use textclip::clip;

/// The pre-#274 body, transcribed EXACTLY from `bench.rs` / `rssi.rs`. Kept so the regression is
/// demonstrable rather than asserted. Do not "fix" this one — it is the exhibit.
fn old_clip(s: &str, n: usize) -> &str {
    &s[..s.len().min(n)]
}

fn main() {
    // The motivating input: a sigil-shaped word carrying one accented character.
    //   bytes:  0:F 1:o 2:r 3:g 4..6:é(C3 A9) 6:d      len 7, chars 6
    // So the cut that lands INSIDE 'é' is byte 5 — NOT 6, which is a boundary (the start of
    // 'd'). Getting that wrong is easy, and the assertion below is what caught it while this
    // suite was being written: a "regression test" aimed one byte off would have passed while
    // proving nothing.
    let word = "Forgéd";
    assert_eq!(word.len(), 7, "test premise: 'Forgéd' is 7 bytes");
    assert_eq!(word.chars().count(), 6, "test premise: 'Forgéd' is 6 chars");
    assert!(!word.is_char_boundary(5), "test premise: byte 5 is inside 'é'");
    assert!(word.is_char_boundary(6), "test premise: byte 6 is a boundary");

    println!("#274 — the old form vs the new one");

    // 1. THE REGRESSION. The old body must still panic here; if it ever stops, this suite is no
    //    longer proving anything and the assertion tells you so loudly rather than going green.
    //    The default hook would print "panicked at ..." to stderr for the panic we are
    //    deliberately provoking, which in a CI log reads exactly like a failure. Silence it for
    //    the duration and restore it immediately, so a real panic anywhere else still reports.
    let prev_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let boom = std::panic::catch_unwind(|| old_clip(word, 5));
    std::panic::set_hook(prev_hook);
    assert!(
        boom.is_err(),
        "the OLD byte-slicing clip did NOT panic on a mid-character cut — this suite's premise \
         is broken, so it is no longer guarding anything",
    );
    println!("  ok      old `&s[..s.len().min(n)]` PANICS at n=5 (inside 'é')");

    // 2. THE FIX. The SAME call that panics above returns cleanly here — the sharpest statement
    //    of what changed.
    assert_eq!(clip(word, 5), "Forgé", "5 chars keeps the accented char whole");
    assert_eq!(clip(word, 6), "Forgéd", "6 chars is the whole word");
    assert_eq!(clip(word, 4), "Forg");
    println!("  ok      new clip(word, 5) = \"Forgé\" — same call, no panic");

    // 3. Exhaustive: EVERY budget on a string full of multi-byte characters must be panic-free
    //    and must round-trip as a prefix. This is the property, not a sample of it.
    for s in ["", "a", "é", "Forgéd", "日本語のノード", "e\u{0301}mile", "🜂🜃🜄🜁", "Ærøskøbing"] {
        for max in 0..=(s.len() + 4) {
            let out = clip(s, max);
            assert!(s.starts_with(out), "clip({s:?}, {max}) = {out:?} is not a prefix");
            assert!(out.chars().count() <= max, "clip({s:?}, {max}) kept too many chars");
            // A shorter budget never yields more text.
            if max > 0 {
                assert!(clip(s, max - 1).len() <= out.len(), "clip is not monotonic in max");
            }
        }
        // A budget at or past the end yields everything.
        assert_eq!(clip(s, s.chars().count()), s);
        assert_eq!(clip(s, usize::MAX), s, "a huge budget must not overflow or truncate");
    }
    println!("  ok      panic-free + prefix + monotonic for every budget on 8 strings");

    // 4. BEHAVIOUR PRESERVATION on today's inputs. The corpus is ASCII, so the new
    //    character-unit clip must agree with the old byte-unit one on every ASCII input —
    //    otherwise this "fix" would silently change what the fleet's screens render.
    let ascii = [
        "Forged", "Ember", "Herald", "smol", "from 10.0.0.1", "v905 12/48",
        "Bellows", "", "a", "abcdefghijklmnop",
    ];
    for s in ascii {
        for max in 0..=(s.len() + 2) {
            assert_eq!(
                clip(s, max),
                old_clip(s, max),
                "ASCII behaviour changed for {s:?} at {max} — the fleet's screens would shift",
            );
        }
    }
    println!("  ok      byte-identical to the old form on every ASCII input (no render change)");

    // 5. The claim that made this a latent bug rather than a live one: today's corpus is ASCII.
    //    Asserted here so that if it ever stops being true, the reason this mattered is on record
    //    next to the fix. (The fix means it no longer matters — that is the point.)
    println!("\nclip_verify: PASS — old form panics, new form does not, ASCII rendering unchanged");
}
